WebLink.url:
{!REQUIRESCRIPT("/soap/ajax/24.0/connection.js")} 
{!REQUIRESCRIPT("/soap/ajax/24.0/apex.js")} 



var newproposal = new sforce.SObject('Proposal__c'); 
newproposal.Opportunity__c ='{!Opportunity.Id}'; 
newproposal.Account__c	= '{!Opportunity.AccountId}'; 
newproposal.Name = '{!Opportunity.Name}'; 
newproposal.Status__c= 'System Created'; 
newproposal.Proposal_Start_Date__c = new Date(); 
newproposal.Proposal_End_Date__c = new Date(); 
newproposal.Forecast_MCA_Revenue__c='1000';

if("{!Opportunity.Forecast_Charter_Spend__c}" != ""){
newproposal.Forecast_Charter_Spend__c ='{!TEXT(Opportunity.Forecast_Charter_Spend__c)}';
}

newproposal.Contact_Information__c='{!JSENCODE(Opportunity.Contact_Information__c)}';
newproposal.Description__c ='{!JSENCODE(Opportunity.Description)}';

var result = sforce.connection.query("Select Id, Name From RecordType Where SobjectType = 'Proposal__c' AND Name = 'Adhoc Charter'");
var records = result.getArray("records");
newproposal.RecordtypeId = records[0].Id;




var result = sforce.connection.create([newproposal]); 

if(result[0].getBoolean("success")) 
{ 
alert('Proposal & Contract has been Created Successfully'); 
window.location = '/' + result[0].id; 
} 
else{ 
alert('Error : '+result); 
}
